@Test
public void testReleasePartitionAndGetNext() throws Exception {
    // Create partition and add some buffers
    SpillableSubpartition partition = new SpillableSubpartition(0, mock(ResultPartition.class), ioManager);
    partition.finish();
    // Create the read view
    ResultSubpartitionView readView = spy(partition.createReadView(new TestInfiniteBufferProvider(), new BufferAvailabilityListener() {

        @Override
        public void notifyBuffersAvailable(long numBuffers) {
        }
