@Test
public void testConsumeSpillablePartitionSpilledDuringConsume() throws Exception {
    ResultPartition parent = mock(ResultPartition.class);
    SpillableSubpartition partition = new SpillableSubpartition(0, parent, ioManager);
    Buffer buffer = new Buffer(MemorySegmentFactory.allocateUnpooledSegment(4096), FreeingBufferRecycler.INSTANCE);
    buffer.retain();
    buffer.retain();
    partition.add(buffer);
    partition.add(buffer);
    partition.add(buffer);
    partition.finish();
    AwaitableBufferAvailablityListener listener = new AwaitableBufferAvailablityListener();
    SpillableSubpartitionView reader = (SpillableSubpartitionView) partition.createReadView(new TestInfiniteBufferProvider(), listener);
    // Initial notification
    assertEquals(1, listener.getNumNotifiedBuffers());
    Buffer read = reader.getNextBuffer();
    assertNotNull(read);
    read.recycle();
    assertEquals(2, listener.getNumNotifiedBuffers());
    // Spill now
    assertEquals(2, partition.releaseMemory());
    listener.awaitNotifications(4, 30_000);
    assertEquals(4, listener.getNumNotifiedBuffers());
    read = reader.getNextBuffer();
    assertNotNull(read);
    read.recycle();
    read = reader.getNextBuffer();
    assertNotNull(read);
    read.recycle();
    // End of partition
    read = reader.getNextBuffer();
    assertNotNull(read);
    assertEquals(EndOfPartitionEvent.class, EventSerializer.fromBuffer(read, ClassLoader.getSystemClassLoader()).getClass());
    read.recycle();
}

private void verifyViewReleasedAfterParentRelease(ResultSubpartition partition) throws Exception {
    // Add a buffer
    Buffer buffer = TestBufferFactory.createBuffer();
    partition.add(buffer);
    partition.finish();
    TestInfiniteBufferProvider buffers = new TestInfiniteBufferProvider();
    // Create the view
    BufferAvailabilityListener listener = mock(BufferAvailabilityListener.class);
    ResultSubpartitionView view = partition.createReadView(buffers, listener);
    // The added buffer and end-of-partition event
    assertNotNull(view.getNextBuffer());
    assertNotNull(view.getNextBuffer());
    // Release the parent
    assertFalse(view.isReleased());
    partition.release();
    // Verify that parent release is reflected at partition view
    assertTrue(view.isReleased());
}

@Test
public void multiThreaded() throws InterruptedException {
    BlockingQueue<Integer> dataChannel = new ArrayBlockingQueue<Integer>(1);
    List<String> actionLog = Lists.newArrayList();
    SerializedUpdateBuffer buffer = Mockito.mock(SerializedUpdateBuffer.class);
    BlockingBackChannel channel = new BlockingBackChannel(buffer);
    Thread head = new Thread(new IterationHead(channel, dataChannel, actionLog));
    Thread tail = new Thread(new IterationTail(channel, dataChannel, actionLog));
    tail.start();
    head.start();
    head.join();
    tail.join();
    //		int action = 0;
    //		for (String log : actionLog) {
    //			System.out.println("ACTION " + (++action) + ": " + log);
    //		}
    assertEquals(12, actionLog.size());
    assertEquals("head sends data", actionLog.get(0));
    assertEquals("tail receives data", actionLog.get(1));
    assertEquals("tail writes in iteration 0", actionLog.get(2));
    assertEquals("head reads in iteration 0", actionLog.get(3));
    assertEquals("head sends data", actionLog.get(4));
    assertEquals("tail receives data", actionLog.get(5));
    assertEquals("tail writes in iteration 1", actionLog.get(6));
    assertEquals("head reads in iteration 1", actionLog.get(7));
    assertEquals("head sends data", actionLog.get(8));
    assertEquals("tail receives data", actionLog.get(9));
    assertEquals("tail writes in iteration 2", actionLog.get(10));
    assertEquals("head reads in iteration 2", actionLog.get(11));
}

