    /* 13 */
    createBarrier(3, 1), // more for the next checkpoint
    /* 14 */
    createBarrier(4, 1), /* 15 */
    createBuffer(0, 100), createBuffer(1, 100), createBuffer(2, 100), // next checkpoint completes
    /* 18 */
    createBarrier(4, 2), // trailing data
    /* 19 */
    createBuffer(0, 100), createBuffer(1, 100), createBuffer(2, 100) };
